    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin-bottom: 30px;
    transition: var(--transition);
}

.blog-back:hover {
    color: var(--primary);
}

.blog-article {
    width: min(900px, 92%);
    margin: 0 auto;
    padding-bottom: 80px;
}

.blog-hero {
    text-align: center;
    margin-bottom: 50px;
}

