    align-items: center;
    justify-content: center;
    font-size: 2rem;
    color: white;
    box-shadow: 0 12px 35px rgba(37, 99, 235, 0.35);
}

.blog-hero h1 {
    font-size: 2.6rem;
    font-weight: 800;
    margin-bottom: 15px;
    line-height: 1.2;
}

.blog-hero .blog-meta {
    color: var(--text-secondary);
    font-size: 0.95rem;
}

.blog-hero .blog-meta span {
    margin: 0 10px;
}

.article-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 35px 40px;
    margin-bottom: 30px;
    backdrop-filter: blur(25px);
    box-shadow: var(--shadow);
}

.article-card h2 {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 20px;
    color: var(--primary);
    text-align: left;
}

.article-card h2::after {
    display: none;
}

.article-card h3 {
    font-size: 1.15rem;
    font-weight: 600;
    margin: 20px 0 12px;
    color: var(--text);
}

.article-card p {
    color: var(--text-secondary);
    margin-bottom: 15px;
    line-height: 1.8;
}

.article-card ul,
.article-card ol {
    color: var(--text-secondary);
    margin: 15px 0 15px 25px;
    line-height: 1.9;
}

.article-card li {
    margin-bottom: 8px;
}

.article-illustration {
    background: rgba(15, 23, 42, 0.6);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 30px;
    margin: 25px 0;
    text-align: center;
}

.article-illustration svg {
    max-width: 100%;
    height: auto;
}

.diagram-flow {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 12px;
    margin: 20px 0;
}

.diagram-step {
    background: rgba(37, 99, 235, 0.15);
    border: 1px solid rgba(37, 99, 235, 0.4);
    border-radius: 12px;
    padding: 14px 20px;
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--text);
    min-width: 100px;
    text-align: center;
}

.diagram-arrow {
    color: var(--primary);
    font-size: 1.4rem;
    font-weight: bold;
}

.info-box {
    background: rgba(37, 99, 235, 0.1);
    border-left: 4px solid var(--primary);
    border-radius: 0 12px 12px 0;
    padding: 18px 22px;
    margin: 20px 0;
}

.info-box p {
    margin: 0;
    color: var(--text);
}

.tip-box {
    background: rgba(16, 185, 129, 0.1);
    border-left: 4px solid var(--success);
    border-radius: 0 12px 12px 0;
    padding: 18px 22px;
    margin: 20px 0;
}

.tip-box p {
    margin: 0;
    color: var(--text);
}

.code-block {
    background: #0a0f1e;
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
    margin: 20px 0;
    overflow-x: auto;
    font-family: 'Consolas', 'Monaco', monospace;
    font-size: 0.88rem;
    line-height: 1.7;
    color: #94a3b8;
}

.code-block .keyword { color: #c084fc; }
.code-block .string { color: #34d399; }
.code-block .comment { color: #64748b; }

.blog-nav-footer {
    display: flex;
