/* ==========================================
   GOOGLE FONT
========================================== */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

/* ==========================================
   VARIÁVEIS
========================================== */
:root {
    --primary: #2563eb;
    --primary-dark: #1d4ed8;
    --secondary: #0f172a;
    --background: #020617;
    --surface: rgba(15, 23, 42, 0.75);
    --surface-light: rgba(30, 41, 59, 0.85);
    --text: #f8fafc;
    --text-secondary: #cbd5e1;
    --border: rgba(255, 255, 255, 0.08);
    --success: #10b981;
    --shadow:
        0 15px 40px rgba(0,0,0,.35);
    --radius: 22px;
    --transition: .35s ease;
}

/* ==========================================
   RESET
========================================== */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: 'Inter', sans-serif;
    background:
        radial-gradient(circle at top left,
        #1e3a8a 0%,
        #0f172a 40%,
        #020617 100%);
    color: var(--text);
    overflow-x: hidden;
    line-height: 1.7;
    min-height: 100vh;
}

/* Fundo com partículas suaves */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background:
        radial-gradient(
            circle at 20% 20%,
            rgba(37,99,235,.20),
            transparent 30%
        ),
        radial-gradient(
            circle at 80% 10%,
            rgba(16,185,129,.15),
            transparent 25%
        ),
        radial-gradient(
            circle at 70% 80%,
            rgba(99,102,241,.18),
            transparent 30%
        );
    z-index: -2;
}

/* Efeito de brilho */
body::after {
    content: "";
    position: fixed;
    width: 700px;
    height: 700px;
    background:
        radial-gradient(
            rgba(37,99,235,.18),
            transparent 70%
        );
    top: -200px;
    right: -150px;
    z-index: -1;
    filter: blur(60px);
}

/* ==========================================
   SCROLLBAR
========================================== */

::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #020617;
}

::-webkit-scrollbar-thumb {
    background: #2563eb;
    border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
    background: #3b82f6;
}

/* ==========================================
   SECTIONS
========================================== */

section {
    width: min(1200px, 92%);
    margin: auto;
    padding: 100px 0;
}

section h2 {
    font-size: 2.4rem;
    font-weight: 800;
    margin-bottom: 50px;
    text-align: center;
    position: relative;
}

section h2::after {
    content: "";
    width: 90px;
    height: 4px;
    background: var(--primary);
    display: block;
    margin: 18px auto;
    border-radius: 10px;
}

/* ==========================================
   LINKS
========================================== */

a {
    color: inherit;
    text-decoration: none;
    transition: var(--transition);
}

a:hover {
    color: var(--primary);
}

/* ==========================================
   IMAGENS
========================================== */

img {
    max-width: 100%;
    display: block;
}

/* ==========================================
   CONTAINER PADRÃO
========================================== */

.container {
    width: min(1200px, 92%);
    margin: auto;
}
/* ==========================================
   NAVBAR
========================================== */

.navbar {
    width: 100%;
    padding: 25px 8%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    position: fixed;
    top: 0;
    left: 0;
