export class CameraController {

    constructor(videoEl) {

        this._videoEl = videoEl;

        navigator.mediaDevices.getUserMedia({

            video: true

        }).then(stream => { 
            
            this._stream = stream;
            let mediaStream = new MediaStream(stream);
            this._videoEl.srcObject = mediaStream;
            this._videoEl.play();

        }).catch(err => {

            console.error(err);

        });

    }

    stopTrack() {

        this._stream.getTracks().forEach(track => {
            track.stop();    
        });

    }

    takePicture(mimeType = 'image/png') {

        let canvas = document.createElement('canvas');
        canvas.setAttribute('height', this._videoEl.videoHeight);
        canvas.setAttribute('width', this._videoEl.videoWidth);

        let context = canvas.getContext('2d');
        context.drawImage(this._videoEl, 0, 0, canvas.width, canvas.height);

        return canvas.toDataURL(mimeType);

    }

}

const pdfjsLib = require('pdfjs-dist');
const path = require('path');
pdfjsLib.GlobalWorkerOptions.workerSrc = path.resolve(__dirname, '../../dist/pdf.worker.bundle.js');

export class DocumentPreviewController {

    constructor(file) {

        this._file = file;

    }

    getPreviewData() {

        return new Promise ((resolve, reject) => {

            let reader = new FileReader();

            switch (this._file.type) {

                case 'image/png':
                case 'image/jpeg':
                case 'image/jpg':
                case 'image/gif':
                   
                    reader.onload = e => {

                        resolve({
                            src: reader.result,
                            info: this._file.name
                        });

                    }
                    reader.onerror = e => {

                        reject(e);

                    }
                    reader.readAsDataURL(this._file);
                break;

                case 'application/pdf':                   

                    reader.onload = e => {

                        pdfjsLib.getDocument(new Uint8Array(reader.result)).then(pdf => {

                            pdf.getPage(1).then(page => {

                                let viewport = page.getViewport(1); // Space Page Visualization
                                let canvas = document.createElement('canvas');
                                let canvasContext = canvas.getContext('2d');
                                canvas.width = viewport.width;
                                canvas.height = viewport.height;

                                page.render({
                                    canvasContext,
                                    viewport
                                }).then(() => {

                                    let _s = (pdf.numPages > 1) ? 's' : '';

                                    resolve({
                                        src: canvas.toDataURL('image/png'),
                                        info: `${pdf.numPages} página${_s}`
                                    });

                                }).catch(err => {
                                    reject(err);
                                });

                            }).catch(err => {
                                reject(err);
                            });

                        }).catch(err => {
                            reject(err);
                        });

                    }
                    reader.readAsArrayBuffer(this._file);

                break;

                default:

                    reject();

            }

        });

    }

}

import { ClassEvent } from "../util/ClassEvent";

export class MicrophoneController extends ClassEvent {

    constructor() {

        super(); // Call the constructor of ClassEvent   
        
        this._mimeType = 'audio/webm';

        this._available = false;

        navigator.mediaDevices.getUserMedia({

            audio: true

        }).then(stream => { 
            
            this._available = true;
            this._stream = stream;                     
            this.trigger('ready', this._stream);

        }).catch(err => {

            console.error(err);

        });


    }

    isAvailable() {

        return this._available;

    }

    stopAudio() {

        this._stream.getTracks().forEach(track => {
            track.stop();    
        });      

    }

    stopRecorder(){

        if (this.isAvailable()) {
        
            this._mediaRecorder.stop();
            this.stopAudio();
            this.stopTimer();

        }

    }

    stopTimer(){

        clearInterval(this._recordMicrophoneInterval);

    }

    startTimer(){

        let start = Date.now();

        this._recordMicrophoneInterval = setInterval(() => {

            this.trigger('recordtimer', (Date.now() - start));

        }, 100);

    }

    startRecorder(){

        if (this.isAvailable()) {            

            this._mediaRecorder = new MediaRecorder(this._stream, {

                mimeType: this._mimeType

            });

            this._recordedChunks = [];

            this._mediaRecorder.addEventListener('dataavailable', e => {

                if (e.data.size > 0) this._recordedChunks.push(e.data);

            });

            this._mediaRecorder.addEventListener('stop', e => {

                let blob = new Blob(this._recordedChunks, {
                    type: this._mimeType
                }); 

                let filename = `rec${Date.now()}.webm`;

                let file = new File([blob], filename, {
                    type: this._mimeType,
                    lastModified: Date.now()
                });

                console.log('file', file);

                let reader = new FileReader();

                reader.onload = e => {

                    console.log('reader file', file);
                    let audio = new Audio(reader.result);
                    audio.play();

                }

                reader.readAsDataURL(file);

            }); 
            
            this._mediaRecorder.start();
            this.startTimer();

        }

    }   
   

}

